$ErrorActionPreference = "Stop"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
Add-Type -AssemblyName System.IO.Compression.FileSystem
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type @'
using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.InteropServices;
public class Demo {
    [DllImport("kernel32.dll", SetLastError=true)] static extern bool ReadProcessMemory(IntPtr process,IntPtr address,byte[] buffer,UIntPtr size,out UIntPtr actual);
    [DllImport("kernel32.dll")] public static extern bool QueryPerformanceFrequency(out long frequency);
    public static uint Read32(IntPtr process,int address) {
        byte[] b=new byte[4]; UIntPtr n;
        if(!ReadProcessMemory(process,new IntPtr(address),b,new UIntPtr(4),out n)||n.ToUInt32()!=4) throw new System.ComponentModel.Win32Exception();
        return BitConverter.ToUInt32(b,0);
    }
    [DllImport("user32.dll")] public static extern void keybd_event(byte vk, byte scan, uint flags, UIntPtr extra);
    [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hwnd, System.Text.StringBuilder buffer, int length);
    public static void Extract(byte[] cab, string root, string[] entries) {
        foreach (string entry in entries) {
            string[] f = entry.Split('|');
            int pos = int.Parse(f[0]), end = pos + int.Parse(f[1]);
            string path = Path.Combine(root, f[3]);
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            using (FileStream output = File.Create(path)) {
                while (pos < end) {
                    int n = BitConverter.ToUInt16(cab, pos);
                    pos += 2;
                    using (var data = new MemoryStream(cab, pos, n))
                    using (var inflater = new DeflateStream(data, CompressionMode.Decompress)) inflater.CopyTo(output);
                    pos += n;
                }
                if (pos != end || output.Length != int.Parse(f[2])) throw new InvalidDataException(f[3]);
            }
        }
    }
}
'@
$root = Join-Path $PWD "revolt"
$zip = Join-Path $PWD "demo.zip"
$game = $null
function shot($label) {
    $bounds = [Windows.Forms.Screen]::PrimaryScreen.Bounds
    $bmp = New-Object Drawing.Bitmap $bounds.Width,$bounds.Height
    $g = [Drawing.Graphics]::FromImage($bmp)
    $g.CopyFromScreen($bounds.Location,[Drawing.Point]::Empty,$bounds.Size)
    $s = New-Object IO.MemoryStream
    $bmp.Save($s,[Drawing.Imaging.ImageFormat]::Jpeg)
    $title = New-Object Text.StringBuilder 256
    [void][Demo]::GetWindowText([Demo]::GetForegroundWindow(),$title,$title.Capacity)
    Write-Output ("frame {0} {1} {2} {3}" -f $label,$bounds.Width,$bounds.Height,$title)
    Write-Output ("jpeg {0} {1}" -f $label,([Convert]::ToBase64String($s.ToArray())))
    $s.Dispose(); $g.Dispose(); $bmp.Dispose()
}
function press([byte]$vk,[byte]$scan) {
    [Demo]::keybd_event($vk,$scan,0,[UIntPtr]::Zero)
    Start-Sleep -Milliseconds 175
    [Demo]::keybd_event($vk,$scan,2,[UIntPtr]::Zero)
}
try {
    [long]$frequency=0
    if(![Demo]::QueryPerformanceFrequency([ref]$frequency)) { throw "no performance counter" }
    Write-Output ("host-frequency " + $frequency)
    $fetcher = New-Object Net.WebClient
    $fetcher.DownloadFile('https://archive.org/download/Re-Volt/Re-voltDemo.zip',$zip)
    if ((Get-FileHash $zip -Algorithm SHA256).Hash -ne '4e0419d459ddc16f60958abc96c7ac5861da869634ff11f78f454d32e1e75cef') { throw 'unexpected archive digest' }
    $z = [IO.Compression.ZipFile]::OpenRead($zip)
    $stream = $z.GetEntry('data1.cab').Open()
    $mem = New-Object IO.MemoryStream
    $stream.CopyTo($mem)
    $stream.Dispose(); $z.Dispose()
    [Demo]::Extract($mem.ToArray(),$root,([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("")).Trim().Split([char]10)))
    $mem.Dispose()
    $game = Start-Process (Join-Path $root "revolt.exe") -ArgumentList "-window" -WorkingDirectory $root -PassThru
    $game.PriorityClass = "BelowNormal"
    Start-Sleep -Seconds 3
    Start-Sleep -Seconds 16
    foreach ($i in 1..15) {
        if ($game.HasExited) { break }
        press 13 28
        Start-Sleep -Seconds 2
        if ($i -eq 14) { shot "grid" }
    }
    [Demo]::keybd_event(38,72,1,[UIntPtr]::Zero)
    Start-Sleep -Seconds 4
    [Demo]::keybd_event(38,72,3,[UIntPtr]::Zero)
    shot "ontrack"
    $handle=$game.Handle
    Write-Output ("game-frequency " + [Demo]::Read32($handle,0x7273d8))
    $elapsed=[Diagnostics.Stopwatch]::StartNew()
    [uint32]$t0=[Demo]::Read32($handle,0x7273d4)
    [uint32]$r0=[Demo]::Read32($handle,0x726cc4)
    for($i=0;$i -lt 4;$i++) {
        Start-Sleep -Milliseconds 550
        $t=[Demo]::Read32($handle,0x7273d4)
        $race=[Demo]::Read32($handle,0x726cc4)
        $origin=[Demo]::Read32($handle,0x726cb4)
        $ticks=([long]$t-[long]$origin) -band 0xffffffffL
        $calc=[Math]::Floor($ticks/[Math]::Floor($frequency/1000))
        Write-Output ("clock sample {0} ms, ticks {1}, start {2}, calculated {3} ms" -f $race,$t,$origin,$calc)
    }
    $sim=@(4294950000L,4294967295L,4294967296L,4294977297L,5162590000L,5947700000L)
    foreach($absolute in $sim) {
        $delta=($absolute -band 0xffffffffL)
        Write-Output ("elapsed ticks {0}, low DWORD {1}, game ms {2}" -f $absolute,$delta,[Math]::Floor($delta/[Math]::Floor($frequency/1000)))
    }
    shot "sampled-native-race"
    if ($game.HasExited) { Write-Output ("exit " + $game.ExitCode) }
    $log = Join-Path $env:TEMP "revolt.log"
    if (Test-Path $log) { Get-Content $log | Select-Object -Last 50 }
    exit 42
} catch {
    Write-Output $_.Exception.ToString()
    exit 1
} finally {
    if ($game -and !$game.HasExited) { $game.Kill(); $game.WaitForExit() }
    if (Test-Path $root) { Remove-Item -Recurse -Force $root }
    if (Test-Path $zip) { Remove-Item $zip }
}
